function build(name, sec) {
  const doc = new Document({ styles: { default: { document: { run: { font: FONT, size: 15 } } } }, sections: [sec] });
  return Packer.toBuffer(doc).then(b => { fs.writeFileSync("./" + name, b); console.log("written", name); });
}
