  for (let i = 1; i <= 3; i++) rows.push(new TableRow({ height: { value: 420, rule: "atLeast" }, children: [cell(String(i), w[0], { bold: true }), cell("", w[1]), cell("", w[2]), cell("", w[3]), cell("", w[4]), cell("", w[5]), cell("", w[6])] }));
  rows.push(new TableRow({ children: [cell([para([run("মোট", { bold: true })], { align: AlignmentType.RIGHT })], 0, { span: 4, fill: GREY }), cell("", w[4], { fill: GREY }), cell("", w[5], { fill: GREY }), cell("", w[6], { fill: GREY })] }));
  const tbl = table(w, rows);
