  const rows = [hdr(["ক্র.নং", "সাপ্লায়ারের নাম (Supplier)", "দর ৳ (প্রতি একক)", "মোট ৳", "সরবরাহের সময়", "বাকির সময়", "মান / আগের অভিজ্ঞতা"], w)];
