  const rule = table([TW], [span([run("স্টোরকিপার নিজে গণনা করবেন না — অন্য কেউ গণনা করবেন। গণনার সময় কোনো মালামাল প্রাপ্তি বা ইস্যু হবে না। প্রতিটি পাতায় দুজনের স্বাক্ষর।", { bold: true, size: 12 })], { fill: LIGHT })]);
  const w = scale([0.04, 0.10, 0.26, 0.06, 0.13, 0.13, 0.11, 0.17]);
