  return section([head, legend(), gap(), hf, gap(), rule, tbl, gap(), note, gap(), sig, gap(), press("অটোকার্বন দুই কপি, মুদ্রিত পাতা নম্বর; আকার A4।")], "ফরম 04-3 · স্টক কাউন্ট শিট");
