  for (let i = 1; i <= 12; i++) rows.push(new TableRow({ height: { value: 360, rule: "atLeast" }, children: [cell(String(i), w[0], { bold: true }), ...Array(13).fill(0).map((_, j) => cell("", w[j + 1]))] }));
  rows.push(new TableRow({ children: [cell([para([run("সর্বমোট", { bold: true })], { align: AlignmentType.RIGHT })], 0, { span: 6, fill: GREY }), ...Array(8).fill(0).map((_, j) => cell("", w[j + 6], { fill: GREY }))] }));
  const tbl = table(w, rows);
