  const rcv = [hdr(["ক্র.নং", "নাম", "নিট ৳", "তারিখ", "মাধ্যম", "প্রাপকের স্বাক্ষর"], wr)];
  for (let i = 1; i <= 6; i++) rcv.push(new TableRow({ height: { value: 360, rule: "atLeast" }, children: [cell(String(i), wr[0], { bold: true }), ...Array(5).fill(0).map((_, j) => cell("", wr[j + 1]))] }));
  const t2 = table(wr, rcv);
